<?php require 'bootstrap.php';require 'layout.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{check_csrf();$s=db()->prepare('SELECT id,name,email,password_hash,role FROM users WHERE email=?');$s->execute([strtolower(trim($_POST['email']??''))]);$u=$s->fetch();if(!$u||!password_verify($_POST['password']??'',$u['password_hash']))throw new RuntimeException();session_regenerate_id(true);unset($u['password_hash']);$_SESSION['user']=$u;redirect('index.php');}catch(Throwable $e){$error='Invalid email or password.';}}head_html('Login');?><h1>Sign in</h1><?php if(isset($_GET['registered'])):?><p class="alert success">Account created. Sign in below.</p><?php endif;?><?php if($error):?><p class="alert"><?=$error?></p><?php endif;?><form method="post" class="panel stack"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn">Login</button></form><?php foot_html();